public class PanchangActivity extends Activity {
    private static final TimeZone IST=TimeZone.getTimeZone("Asia/Kolkata");
    private final ExecutorService worker=Executors.newSingleThreadExecutor();
    private final Handler main=new Handler(Looper.getMainLooper());
    private final Runnable todayRefresh=()->render();
    private Calendar selected=Calendar.getInstance(IST); private LinearLayout content,actions,screenRoot; private TextView loading; private boolean pickerOpen, backDown; private int generation; private View changeBackground; private ImageView moonView; private LinearLayout headerBar; private Bitmap backgroundBitmap;
    /** Close the Panchang screen and return to the launcher Home. */
    private void goHome(){backDown=false;Intent home=new Intent(this,MainActivity.class);home.addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP);try{startActivity(home);}catch(RuntimeException ignored){}finish();}
    @Override public void onBackPressed(){if(!pickerOpen)goHome();}
    @Override public void onCreate(Bundle b){super.onCreate(b);selected.set(Calendar.HOUR_OF_DAY,12);build();content.requestFocus();render();}
    private int dp(float v){return (int)(v*getResources().getDisplayMetrics().density+.5f);}
    private TextView label(String s,int size,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextColor(Color.WHITE);t.setTextSize(size);t.setPadding(dp(8),dp(4),dp(8),dp(4));t.setFontFeatureSettings("kern");t.setTypeface(getResources().getFont(bold?R.font.outfit_medium:R.font.outfit_regular));return t;}
    private ImageButton iconButton(int icon,String desc,View.OnClickListener l){ImageButton b=new ImageButton(this);b.setImageResource(icon);b.setContentDescription(desc);b.setBackgroundResource(R.drawable.pill_bg);b.setImageTintList(new android.content.res.ColorStateList(new int[][]{{android.R.attr.state_focused},{}},new int[]{0xFF111111,0xFFFFFFFF}));b.setScaleType(ImageView.ScaleType.CENTER);b.setFocusable(true);b.setOnClickListener(l);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(dp(52),dp(42));lp.setMarginStart(dp(10));b.setLayoutParams(lp);return b;}
    private void build(){LinearLayout root=new LinearLayout(this);screenRoot=root;root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(36),dp(20),dp(36),dp(16));Config cfg=Config.load(this);root.setBackgroundColor(cfg.backgroundColor);if(cfg.wallpaper!=null){BitmapFactory.Options options=new BitmapFactory.Options();options.inSampleSize=2;options.inPreferredConfig=Bitmap.Config.RGB_565;Bitmap wallpaper=BitmapFactory.decodeFile(cfg.wallpaper.getAbsolutePath(),options);if(wallpaper!=null){backgroundBitmap=wallpaper;root.setBackground(new BitmapDrawable(getResources(),wallpaper));}}setContentView(root);LinearLayout header=new LinearLayout(this);header.setOrientation(LinearLayout.HORIZONTAL);header.setGravity(Gravity.CENTER_VERTICAL);headerBar=header;loading=label("Panchang",28,true);header.addView(loading,new LinearLayout.LayoutParams(0,-2,1));moonView=new ImageView(this);moonView.setContentDescription("Moon phase");LinearLayout.LayoutParams moonLp=new LinearLayout.LayoutParams(dp(44),dp(44));moonLp.setMarginEnd(dp(8));header.addView(moonView,moonLp);header.addView(iconButton(R.drawable.ic_back,"Back",v->goHome()));changeBackground=iconButton(R.drawable.ic_wallpaper,"Change background",v->nextBackground());header.addView(changeBackground);root.addView(header);ScrollView sc=new ScrollView(this);content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);content.setFocusable(true);sc.addView(content);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));actions=new LinearLayout(this);actions.setGravity(Gravity.CENTER);root.addView(actions);String[] names={"Previous day","Today","Pick date","Next day"};for(int i=0;i<names.length;i++){final int which=i;Button b=new Button(this);b.setText(names[i]);b.setFocusable(true);b.setOnClickListener(v->{if(which==0)addDay(-1);else if(which==1){selected=Calendar.getInstance(IST);render();}else if(which==2)openPicker();else addDay(1);});actions.addView(b,new LinearLayout.LayoutParams(0,dp(54),1));}loadBackground(); }
    private int bgFailures;
    private void nextBackground(){List<PhotoStore.Photo> photos=PhotoStore.list(this,PhotoStore.chosenSource(this));if(photos.isEmpty())return;java.util.ArrayList<String> files=new java.util.ArrayList<>();for(PhotoStore.Photo photo:photos)files.add(photo.file);String current=getSharedPreferences(Config.SETTINGS_NAME,MODE_PRIVATE).getString("panchang_bg","");String selected=PhotoBackgroundCycle.nextFile(files,current);getSharedPreferences(Config.SETTINGS_NAME,MODE_PRIVATE).edit().putString("panchang_bg",selected).apply();loadBackground();}
    private void loadBackground(){List<PhotoStore.Photo> photos=PhotoStore.list(this,PhotoStore.chosenSource(this));if(photos.isEmpty()){changeBackground.setEnabled(false);return;}changeBackground.setEnabled(true);String wanted=getSharedPreferences(Config.SETTINGS_NAME,MODE_PRIVATE).getString("panchang_bg","");boolean found=false;for(PhotoStore.Photo p:photos)if(p.file.equals(wanted))found=true;if(!found){wanted=photos.get(PhotoShuffle.pick(photos.size(),-1,new java.util.Random())).file;getSharedPreferences(Config.SETTINGS_NAME,MODE_PRIVATE).edit().putString("panchang_bg",wanted).apply();}final String file=wanted;worker.execute(()->{BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;BitmapFactory.decodeFile(new File(PhotoStore.dir(this),file).getAbsolutePath(),o);int w=getResources().getDisplayMetrics().widthPixels,h=getResources().getDisplayMetrics().heightPixels,sample=1;while(sample<1024&&(o.outWidth/sample>w||o.outHeight/sample>h))sample*=2;o.inJustDecodeBounds=false;o.inSampleSize=sample;o.inPreferredConfig=Bitmap.Config.RGB_565;Bitmap b=BitmapFactory.decodeFile(new File(PhotoStore.dir(this),file).getAbsolutePath(),o);main.post(()->{if(isFinishing())return;if(b==null){android.util.Log.w("TvHomePhotos","panchang bg decode failed: "+file);if(bgFailures++<3){nextBackground();return;}changeBackground.setEnabled(false);return;}bgFailures=0;Bitmap old=backgroundBitmap;backgroundBitmap=b;BitmapDrawable image=new BitmapDrawable(getResources(),b);image.setAlpha(255);screenRoot.setBackground(new LayerDrawable(new android.graphics.drawable.Drawable[]{image,new ColorDrawable(0x99000000)}));});});}
    private void addDay(int n){selected.add(Calendar.DAY_OF_MONTH,n);render();}
    @Override public boolean dispatchKeyEvent(KeyEvent e){int kc=e.getKeyCode();if((kc==KeyEvent.KEYCODE_BACK||kc==KeyEvent.KEYCODE_ESCAPE)&&!pickerOpen){if(e.getAction()==KeyEvent.ACTION_DOWN){if(e.getRepeatCount()==0)backDown=true;return true;}if(e.getAction()==KeyEvent.ACTION_UP){boolean go=backDown&&!e.isCanceled();backDown=false;if(go)goHome();return true;}}if(e.getAction()==KeyEvent.ACTION_DOWN&&!pickerOpen){View f=getCurrentFocus();boolean onActions=false;while(f!=null){if(f==actions||f==headerBar){onActions=true;break;}android.view.ViewParent p=f.getParent();f=p instanceof View?(View)p:null;}if(!onActions&&e.getKeyCode()==KeyEvent.KEYCODE_DPAD_LEFT){addDay(-1);return true;}if(!onActions&&e.getKeyCode()==KeyEvent.KEYCODE_DPAD_RIGHT){addDay(1);return true;}}return super.dispatchKeyEvent(e);}
    private void render(){final int y=selected.get(Calendar.YEAR),m=selected.get(Calendar.MONTH)+1,d=selected.get(Calendar.DAY_OF_MONTH),request=++generation;loading.setText("Loading Panchang...");worker.execute(()->{Panchang.DayEvents data=new Panchang.DayEvents(y,m,d);main.post(()->{if(request==generation)show(data);});});}
    private String nextDate(Calendar next){SimpleDateFormat f=new SimpleDateFormat("MMM d",Locale.US);f.setTimeZone(IST);return f.format(next.getTime());}
    private String tm(double jd){if(Double.isNaN(jd))return "";SimpleDateFormat f=new SimpleDateFormat("h:mm a",Locale.US);f.setTimeZone(IST);return f.format(new Date((long)((jd-2440587.5)*86400000)));}
    private String timed(double jd,int y,int m,int d){if(Double.isNaN(jd))return "Not available";Calendar c=(Calendar)selected.clone();c.set(y,m-1,d,0,0,0);double dayStart=Panchang.julianDay(y,m,d,0,0)-5.5/24.0;String out=tm(jd);if(jd>=dayStart+1){Calendar next=(Calendar)c.clone();next.add(Calendar.DAY_OF_MONTH,1);out+=", "+nextDate(next);}return out;}
    private void row(LinearLayout col,String title,String value){LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(8),dp(6),dp(8),dp(6));TextView a=label(title,15,true),b=label(value,19,false);box.addView(a);box.addView(b);col.addView(box);}
    private String after(double end,java.util.function.DoubleFunction<String> name,java.util.function.DoubleFunction<Double> nextEnd,int y,int m,int d){double t=end+0.00001;return "till "+timed(end,y,m,d)+", then "+name.apply(t)+" till "+timed(nextEnd.apply(t),y,m,d);}
    private String afterTwice(double end,java.util.function.DoubleFunction<String> name,java.util.function.DoubleFunction<Double> nextEnd,int y,int m,int d){double t=end+0.00001,n=nextEnd.apply(t);return "till "+timed(end,y,m,d)+", then "+name.apply(t)+" till "+timed(n,y,m,d)+", then "+name.apply(n+0.00001);}
    private void show(Panchang.DayEvents e){content.removeAllViews();int y=selected.get(Calendar.YEAR),m=selected.get(Calendar.MONTH)+1,d=selected.get(Calendar.DAY_OF_MONTH);SimpleDateFormat headerFormat=new SimpleDateFormat("EEEE, d MMMM yyyy",Locale.US);headerFormat.setTimeZone(IST);String greg=headerFormat.format(selected.getTime());loading.setText("Panchang  \u00B7  "+greg);LinearLayout cols=new LinearLayout(this);content.addView(cols);LinearLayout[] c=new LinearLayout[3];for(int i=0;i<3;i++){c[i]=new LinearLayout(this);c[i].setOrientation(LinearLayout.VERTICAL);cols.addView(c[i],new LinearLayout.LayoutParams(0,-2,1));}
        Calendar wd=(Calendar)selected.clone();String[] hindi={"","Ravivara","Somavara","Mangalavara","Budhavara","Guruvara","Shukravara","Shanivara"};row(c[0],"Hindu date",e.base.monthDisplay+" (Amanta), "+e.base.paksha+" Paksha");row(c[0],"Samvat","Shalivahana Shaka "+e.base.shakaSamvat);row(c[0],"Weekday",new SimpleDateFormat("EEEE",Locale.US).format(selected.getTime())+"  \u00B7  "+hindi[wd.get(Calendar.DAY_OF_WEEK)]);row(c[0],"Sunrise / sunset",tm(e.base.sunriseJd)+" / "+tm(e.sunset));row(c[0],"Moonrise / moonset",(Double.isNaN(e.moonrise)?"No moonrise today":timed(e.moonrise,y,m,d))+" / "+(Double.isNaN(e.moonset)?"No moonset today":timed(e.moonset,y,m,d)));
        row(c[1],"Tithi",e.base.tithiName+" ("+e.base.paksha+") "+after(e.tithiEnd,t->Panchang.currentTithiName(t)+" ("+Panchang.currentPaksha(t)+")",Panchang::tithiEndJd,y,m,d));row(c[1],"Nakshatra",e.base.nakshatra+" "+after(e.nakshatraEnd,Panchang::currentNakshatra,Panchang::nakshatraEndJd,y,m,d));row(c[1],"Yoga",Panchang.yoga(e.base.sunriseJd)+" "+after(e.yogaEnd,Panchang::yoga,Panchang::yogaEndJd,y,m,d));row(c[1],"Karana",Panchang.karana(e.base.sunriseJd)+" "+afterTwice(e.karanaEnd,Panchang::karana,Panchang::karanaEndJd,y,m,d));if(moonView!=null)moonView.setImageDrawable(new PanchangDisplay.MoonDrawable(e.base.sunriseJd));row(c[1],"Moon sign",Panchang.moonRashi(e.base.sunriseJd)+" till "+timed(e.moonRashiEnd,y,m,d));row(c[1],"Sun sign",Panchang.sunRashi(e.base.sunriseJd)+" till "+timed(e.sunRashiEnd,y,m,d));
        row(c[2],"Rahu Kalam",tm(e.rahuStart)+" - "+tm(e.rahuEnd));row(c[2],"Yamaganda",tm(e.yamagandaStart)+" - "+tm(e.yamagandaEnd));row(c[2],"Gulikai Kalam",tm(e.gulikaStart)+" - "+tm(e.gulikaEnd));String ab=tm(e.abhijitStart)+" - "+tm(e.abhijitEnd);Calendar now=Calendar.getInstance(IST);if(y==now.get(Calendar.YEAR)&&m==now.get(Calendar.MONTH)+1&&d==now.get(Calendar.DAY_OF_MONTH)){double n=PanchangDisplay.jdNow();if(n>=e.abhijitStart&&n<=e.abhijitEnd)ab="NOW  \u00B7  "+ab;}if(wd.get(Calendar.DAY_OF_WEEK)==Calendar.WEDNESDAY)ab+=" (not observed on Wednesday)";row(c[2],"Abhijit Muhurta",ab);row(c[2],"Festival",e.base.festival.isEmpty()?"No listed observance":e.base.festival);
        TextView credit=label("Computed offline (Lahiri)",12,false);content.addView(credit);main.removeCallbacks(todayRefresh);if(y==now.get(Calendar.YEAR)&&m==now.get(Calendar.MONTH)+1&&d==now.get(Calendar.DAY_OF_MONTH))scheduleTodayRefresh(e,now); }
    private void scheduleTodayRefresh(Panchang.DayEvents e,Calendar now){double jd=PanchangDisplay.jdNow(),next=Double.POSITIVE_INFINITY;double[] changes={Panchang.tithiEndJd(jd),Panchang.nakshatraEndJd(jd),Panchang.yogaEndJd(jd),Panchang.karanaEndJd(jd),Panchang.moonRashiEndJd(jd),Panchang.solarRashiEndJd(jd),e.rahuStart,e.rahuEnd,e.yamagandaStart,e.yamagandaEnd,e.gulikaStart,e.gulikaEnd,e.abhijitStart,e.abhijitEnd};for(double x:changes)if(x>jd)next=Math.min(next,x);Calendar midnight=(Calendar)now.clone();midnight.add(Calendar.DAY_OF_MONTH,1);midnight.set(Calendar.HOUR_OF_DAY,0);midnight.set(Calendar.MINUTE,0);midnight.set(Calendar.SECOND,0);midnight.set(Calendar.MILLISECOND,0);long delay=Math.min(midnight.getTimeInMillis()-System.currentTimeMillis(),(long)((next-jd)*86400000));main.postDelayed(todayRefresh,Math.max(1000,delay));}
    private void openPicker(){pickerOpen=true;Calendar v=(Calendar)selected.clone();LinearLayout panel=new LinearLayout(this);panel.setPadding(dp(16),dp(16),dp(16),dp(16));String[] months=new SimpleDateFormat("MMMM",Locale.US).getDateFormatSymbols().getMonths();int[] vals={v.get(Calendar.DAY_OF_MONTH),v.get(Calendar.MONTH)+1,v.get(Calendar.YEAR)};String[] prefix={"Day ","Month ","Year "};TextView[] fields=new TextView[3];final int[] focus={0};final AlertDialog[] dialogRef={null};for(int i=0;i<3;i++){final int ix=i;fields[i]=label(prefix[i]+(i==1?months[vals[i]-1]:vals[i]),24,true);fields[i].setFocusable(true);fields[i].setBackgroundResource(R.drawable.calendar_focus);fields[i].setOnKeyListener((view,key,event)->{int k=event.getKeyCode();if(event.getAction()!=KeyEvent.ACTION_DOWN)return true;if(k==KeyEvent.KEYCODE_DPAD_LEFT||k==KeyEvent.KEYCODE_DPAD_RIGHT){focus[0]=Math.max(0,Math.min(2,ix+(k==KeyEvent.KEYCODE_DPAD_LEFT?-1:1)));fields[focus[0]].requestFocus();return true;}if(k==KeyEvent.KEYCODE_DPAD_UP||k==KeyEvent.KEYCODE_DPAD_DOWN){int delta=k==KeyEvent.KEYCODE_DPAD_UP?1:-1;vals[ix]+=delta;if(ix==0)vals[ix]=Math.max(1,Math.min(Panchang.clampDay(vals[2],vals[1],vals[0]),vals[ix]));else if(ix==1)vals[ix]=Math.max(1,Math.min(12,vals[ix]));else vals[ix]=Math.max(1900,Math.min(2100,vals[ix]));vals[0]=Panchang.clampDay(vals[2],vals[1],vals[0]);fields[ix].setText(prefix[ix]+(ix==1?months[vals[ix]-1]:vals[ix]));fields[0].setText(prefix[0]+vals[0]);return true;}if(k==KeyEvent.KEYCODE_BACK||k==KeyEvent.KEYCODE_ESCAPE){backDown=false;if(dialogRef[0]!=null)dialogRef[0].cancel();return true;}if(k==KeyEvent.KEYCODE_DPAD_CENTER||k==KeyEvent.KEYCODE_ENTER){selected.set(vals[2],vals[1]-1,1);selected.set(Calendar.DAY_OF_MONTH,Panchang.clampDay(vals[2],vals[1],vals[0]));if(dialogRef[0]!=null)dialogRef[0].dismiss();render();return true;}return false;});panel.addView(fields[i],new LinearLayout.LayoutParams(0,dp(72),1));}AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Pick date  \u00B7  LEFT/RIGHT select, UP/DOWN change, OK apply").setView(panel).setOnCancelListener(x->{pickerOpen=false;backDown=false;}).create();dialogRef[0]=dialog;dialog.setOnDismissListener(x->{pickerOpen=false;backDown=false;});dialog.show();fields[0].requestFocus(); }
    
    @Override protected void onDestroy(){generation++;main.removeCallbacks(todayRefresh);if(screenRoot!=null)screenRoot.setBackground(null);backgroundBitmap=null;super.onDestroy();worker.shutdownNow();}
}
